import {
  isEngineeringPreviewDrafts,
  isEngineeringPreviewWeeks,
  type EngineeringPreviewDraft,
  type EngineeringPreviewWeek,
} from './engineering-preview.models';
import {
  isWalkthroughTask,
  type DesignWalkthroughTask,
} from '../../../shared/engineering/design-walkthrough';
import {
  isBlockDesign,
  isDesignCapture,
  isDesignChecks,
  type DesignCheck,
  type BlockDesign,
  type DesignCapture,
} from '../../../shared/engineering/block-design';
export interface EngineeringDesignConfig {
  readonly previewWeeks?: readonly EngineeringPreviewWeek[];
  readonly schemaVersion: '1.0';
  readonly projectId: string;
  readonly version: string;
  readonly template: { readonly id: 'engineering-design'; readonly version: '1.0' };
  readonly title: string;
  readonly mission: string;
  readonly simulationId: string;
  readonly research: readonly {
    readonly id: string;
    readonly title: string;
    readonly prompt: string;
    readonly explanation: string;
    readonly source: { readonly label: string; readonly url: string };
  }[];
  readonly designBrief: string;
  readonly testInstructions: readonly string[];
  readonly exhibitPrompts: readonly string[];
  readonly starterDesign: BlockDesign;
  readonly starterChecks?: readonly DesignCheck[];
  readonly designSamples?: readonly EngineeringDesignSample[];
  readonly learningSequence?: {
    readonly practiceDesign: BlockDesign;
    readonly steps: readonly EngineeringLearningStep[];
  };
}
/** Ordered curriculum prompts; the installed simulation owns each activity's behavior. */
export interface EngineeringLearningStep {
  readonly tasks?: readonly DesignWalkthroughTask[];
  readonly id: string;
  readonly title: string;
  readonly introduction: string;
  readonly instructions: readonly string[];
  readonly workspace: 'practice' | 'project';
  readonly activity: string;
  readonly question?: { readonly researchId: string; readonly prompt: string };
  readonly explanation?: string;
  readonly showGuides?: boolean;
}
export interface EngineeringDesignSample {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly design: BlockDesign;
  readonly checks?: readonly DesignCheck[];
}
export interface EngineeringSnapshot {
  readonly previewDrafts?: Readonly<Record<string, EngineeringPreviewDraft>>;
  readonly schemaVersion: '1.0';
  readonly revision: number;
  readonly learningStepId?: string;
  readonly learningTaskId?: string;
  readonly walkthroughNotes?: Readonly<Record<string, string>>;
  readonly practiceDesign?: BlockDesign;
  readonly design: BlockDesign;
  readonly research: Readonly<Record<string, string>>;
  readonly prediction: string;
  readonly exhibit: string;
  readonly checks?: readonly DesignCheck[];
  readonly designBackup?: { readonly design: BlockDesign; readonly checks: readonly DesignCheck[] };
  readonly trials: readonly (DesignCapture & { readonly prediction: string })[];
  readonly events: readonly {
    readonly id: string;
    readonly eventType: string;
    readonly timestamp: string;
  }[];
}
const record = (v: unknown): v is Record<string, unknown> =>
  !!v && typeof v === 'object' && !Array.isArray(v);
const text = (v: unknown): v is string => typeof v === 'string' && !!v.trim() && v.length <= 10000;
export function requireEngineeringConfig(v: unknown, projectId: string): EngineeringDesignConfig {
  if (
    !record(v) ||
    v['schemaVersion'] !== '1.0' ||
    v['projectId'] !== projectId ||
    !text(v['version']) ||
    !/^\d+\.\d+\.\d+$/.test(v['version']) ||
    !record(v['template']) ||
    v['template']['id'] !== 'engineering-design' ||
    v['template']['version'] !== '1.0' ||
    !['title', 'mission', 'simulationId', 'designBrief'].every((k) => text(v[k])) ||
    !isBlockDesign(v['starterDesign']) ||
    (v['starterChecks'] !== undefined && !isDesignChecks(v['starterChecks'])) ||
    !Array.isArray(v['research']) ||
    !v['research'].length ||
    v['research'].some(
      (r: unknown) =>
        !record(r) ||
        !['id', 'title', 'prompt', 'explanation'].every((k) => text(r[k])) ||
        !record(r['source']) ||
        !text(r['source']['label']) ||
        !text(r['source']['url']) ||
        !r['source']['url'].startsWith('https://'),
    ) ||
    !['testInstructions', 'exhibitPrompts'].every(
      (k) => Array.isArray(v[k]) && v[k].length > 0 && v[k].every(text),
    )
  ) {
    throw new Error('CONFIG_INVALID: The engineering design package is incomplete or unsupported.');
  }
  const config = v as unknown as EngineeringDesignConfig;
  if (config.previewWeeks !== undefined && !isEngineeringPreviewWeeks(config.previewWeeks))
    throw new Error('CONFIG_INVALID: Invalid engineering preview weeks.');
  if (
    config.designSamples !== undefined &&
    (!Array.isArray(config.designSamples) ||
      config.designSamples.length > 12 ||
      config.designSamples.some(
        (s) =>
          !record(s) ||
          !text(s['id']) ||
          !text(s['title']) ||
          !text(s['description']) ||
          !isBlockDesign(s['design']) ||
          (s['checks'] !== undefined && !isDesignChecks(s['checks'])),
      ) ||
      new Set(config.designSamples.map((s) => s.id)).size !== config.designSamples.length)
  )
    throw new Error('CONFIG_INVALID: Invalid sample design library.');
  if (new Set(config.research.map((r) => r.id)).size !== config.research.length)
    throw new Error('CONFIG_INVALID: Research IDs must be unique.');
  const validStep = (step: unknown): boolean => {
    if (!record(step)) return false;
    const question = step['question'];
    return (
      ['id', 'title', 'introduction', 'activity'].every((k) => text(step[k])) &&
      ['practice', 'project'].includes(String(step['workspace'])) &&
      Array.isArray(step['instructions']) &&
      step['instructions'].length > 0 &&
      step['instructions'].length <= 8 &&
      step['instructions'].every(text) &&
      (step['explanation'] === undefined || text(step['explanation'])) &&
      (step['showGuides'] === undefined || typeof step['showGuides'] === 'boolean') &&
      (step['tasks'] === undefined ||
        (Array.isArray(step['tasks']) &&
          step['tasks'].length > 0 &&
          step['tasks'].length <= 12 &&
          step['tasks'].every(isWalkthroughTask) &&
          new Set(step['tasks'].map((t) => t.id)).size === step['tasks'].length &&
          step['tasks'].every(
            (t) => !t.sampleId || config.designSamples?.some((s) => s.id === t.sampleId),
          ))) &&
      (question === undefined ||
        (record(question) &&
          text(question['prompt']) &&
          config.research.some((r) => r.id === question['researchId'])))
    );
  };
  const sequence = config.learningSequence;
  if (
    sequence !== undefined &&
    (!record(sequence) ||
      !isBlockDesign(sequence.practiceDesign) ||
      !Array.isArray(sequence.steps) ||
      !sequence.steps.length ||
      sequence.steps.length > 10 ||
      !sequence.steps.every(validStep) ||
      new Set(sequence.steps.map((step) => step.id)).size !== sequence.steps.length ||
      sequence.steps[sequence.steps.length - 1].workspace !== 'project')
  )
    throw new Error('CONFIG_INVALID: Invalid engineering learning sequence.');
  return config;
}
export function isEngineeringSnapshot(v: unknown): v is EngineeringSnapshot {
  return (
    record(v) &&
    (v['previewDrafts'] === undefined || isEngineeringPreviewDrafts(v['previewDrafts'])) &&
    v['schemaVersion'] === '1.0' &&
    Number.isInteger(v['revision']) &&
    (v['revision'] as number) >= 0 &&
    (v['learningStepId'] === undefined || text(v['learningStepId'])) &&
    (v['learningTaskId'] === undefined || text(v['learningTaskId'])) &&
    (v['walkthroughNotes'] === undefined ||
      (record(v['walkthroughNotes']) &&
        Object.keys(v['walkthroughNotes']).length <= 120 &&
        Object.entries(v['walkthroughNotes']).every(
          ([k, n]) => k.length <= 250 && typeof n === 'string' && n.length <= 2000,
        ))) &&
    (v['practiceDesign'] === undefined || isBlockDesign(v['practiceDesign'])) &&
    isBlockDesign(v['design']) &&
    record(v['research']) &&
    Object.keys(v['research']).length <= 30 &&
    Object.values(v['research']).every((t) => typeof t === 'string' && t.length <= 10000) &&
    typeof v['prediction'] === 'string' &&
    v['prediction'].length <= 10000 &&
    typeof v['exhibit'] === 'string' &&
    v['exhibit'].length <= 10000 &&
    (v['checks'] === undefined || isDesignChecks(v['checks'])) &&
    (v['designBackup'] === undefined ||
      (record(v['designBackup']) &&
        isBlockDesign(v['designBackup']['design']) &&
        isDesignChecks(v['designBackup']['checks']))) &&
    Array.isArray(v['trials']) &&
    v['trials'].length <= 40 &&
    v['trials'].every(
      (t: unknown) =>
        isDesignCapture(t) &&
        'prediction' in t &&
        typeof t.prediction === 'string' &&
        t.prediction.length <= 10000,
    ) &&
    Array.isArray(v['events']) &&
    v['events'].length <= 200 &&
    v['events'].every(
      (e: unknown) => record(e) && text(e['id']) && text(e['eventType']) && text(e['timestamp']),
    )
  );
}
